import React, { useState, useEffect, useMemo } from 'react'
import GrowShrinkTag from 'components/shared/GrowShrinkTag'
import { GoPrimitiveDot } from 'react-icons/go'
import { Card } from 'components/ui'
import Button from "components/ui/Buttons"
import { Link } from "react-router-dom"
import DataTable from 'components/shared/DataTable'
import Avatar from 'components/ui/Avatar'

const Home = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(false)
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
    })

    const columns = useMemo(() => {
        return [
            {
                header: 'Task Name',
                accessorKey: 'taskName',
            },
            {
                header: 'Assign To',
                accessorKey: 'assignTo',
            },
            {
                header: 'Priority',
                // accessorKey: 'priority',
                cell: (props) => (<div className={'tag text-' + (props.row.original.priority === 'High' ? 'red' : props.row.original.priority === 'Low' ? 'blue' : 'amber') + '-600 bg-' + (props.row.original.priority === 'High' ? 'red' : props.row.original.priority === 'Low' ? 'blue' : 'amber') + '-100 dark:text-' + (props.row.original.priority === 'High' ? 'red' : props.row.original.priority === 'Low' ? 'blue' : 'amber') + '-100 dark:bg-' + (props.row.original.priority === 'High' ? 'red' : props.row.original.priority === 'Low' ? 'blue' : 'amber') + '-500/20 rounded border-0'}>{props.row.original.priority}</div>)
            },
            {
                header: 'Due Date',
                accessorKey: 'dueDate'
            },
            {
                header: 'Status',
                accessorKey: 'status'
            },
            {
                header: 'Assignees',
                // accessorKey:'', 
                cell: (props) => (
                    <Avatar.Group
                        chained
                        maxCount={3}
                        omittedAvatarProps={{ shape: 'circle' }}
                        omittedAvatarTooltip
                        onOmittedAvatarClick={() => console.log('Omitted Avatar Clicked')}
                    >
                        {
                            props.row.original.photo <= 1 ? (
                                <>
                                    <Avatar shape="circle" src="/img/avatars/thumb-1.jpg" />
                                </>
                            )
                                : props.row.original.photo <= 2 ? (
                                    <>
                                        <Avatar shape="circle" src="/img/avatars/thumb-1.jpg" />
                                        <Avatar shape="circle" src="/img/avatars/thumb-10.jpg" />
                                    </>
                                ) : props.row.original.photo <= 3 ? (
                                    <>
                                        <Avatar shape="circle" src="/img/avatars/thumb-1.jpg" />
                                        <Avatar shape="circle" src="/img/avatars/thumb-10.jpg" />
                                        <Avatar shape="circle" src="/img/avatars/thumb-1.jpg" />
                                    </>
                                ) : (
                                    <>
                                        <Avatar shape="circle" src="/img/avatars/thumb-10.jpg" />
                                        <Avatar shape="circle" src="/img/avatars/thumb-1.jpg" />
                                        <Avatar shape="circle" src="/img/avatars/thumb-10.jpg" />
                                        <Avatar shape="circle" src="/img/avatars/thumb-1.jpg" />
                                    </>
                                )
                        }
                    </Avatar.Group>
                )

            },
            {
                header: 'Action',
                cell: (props) => (
                    <Button size="xs" onClick={() => console.log('Action clicked', props)}>
                        Action
                    </Button>
                ),
            },
        ]
    }, [])

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            sort: { order, key }
        }))
    }

    console.log("Home.js Loading....")

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true)
            // const response = await axios.post('/api/crm/customers', tableData)
            // if (response.data) {
            // }
            let data = {
                data: [
                    {
                        id: 1,
                        taskName: 'task 1',
                        assignTo: 'Sau 1',
                        priority: 'High',
                        dueDate: '12/12/2024',
                        status: 'Active',
                        photo: 2
                    },
                    {
                        id: 1,
                        taskName: 'task 2',
                        assignTo: 'Sau 2',
                        priority: 'Low',
                        dueDate: '12/12/2024',
                        status: 'Active',
                        photo: 1
                    },
                    {
                        id: 1,
                        taskName: 'task 3',
                        assignTo: 'Sau 3',
                        priority: 'Medium',
                        dueDate: '12/12/2024',
                        status: 'Active',
                        photo: 3
                    },
                    {
                        id: 1,
                        taskName: 'task 4',
                        assignTo: 'Sau 4',
                        priority: 'High',
                        dueDate: '12/12/2024',
                        status: 'Active',
                        photo: 2
                    },
                    {
                        id: 1,
                        taskName: 'task 5',
                        assignTo: 'Sau 5',
                        priority: 'Low',
                        dueDate: '12/12/2024',
                        status: 'Active',
                        photo: 1
                    },
                    {
                        id: 1,
                        taskName: 'task 6',
                        assignTo: 'Sau 6',
                        priority: 'Medium',
                        dueDate: '12/12/2024',
                        status: 'Active',
                        photo: 3
                    }
                ],
                total: 10
            }
            setData(data.data)
            setLoading(false)
            setTableData((prevData) => ({
                ...prevData,
                ...{ total: data.total },
            }))
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [tableData.pageIndex, tableData.sort, tableData.pageSize])
    return (
        <>
            <Card className=" card-shadow mb-4">
                <div className="flex justify-between items-center mb-8">
                    <h4>Purchase Order</h4>
                    <div>
                        <Link to={'/transaction/purchase-order/add-purchase-order'}>
                            <Button size="sm" variant="solid" color="rose-500" className="mr-2">Raise PO</Button>
                        </Link>
                        <Link to={'/transaction/finance-voucher'}>
                            <Button size="sm" variant="solid" color="amber-500" className="mr-2">Payment</Button>
                        </Link>
                        <Link to={'/transaction/raw-material-qty-in/add-raw-material-qty-in'}>
                            <Button size="sm" variant="solid" color="emerald-500">Raw Material In</Button>
                        </Link>
                    </div>
                </div>
                <div className="grid lg:grid-cols-2 2xl:grid-cols-4 gap-4">
                    <Card className="bg-gray-50 dark:bg-gray-700 border-0 card-shadow">
                        <div className="flex items-center justify-between my-2">
                            <div className="flex items-center gap-1">
                                <span className="avatar avatar-circle avatar-md bg-transparent">
                                    <GoPrimitiveDot
                                        size={'40px'}
                                        className="text-blue-500"
                                    ></GoPrimitiveDot>
                                </span>
                                <div>
                                    <h6 className="font-bold">
                                        Approval Pending
                                    </h6>
                                    <p>View All</p>
                                </div>
                            </div>
                            <div className="text-right rtl:text-left">
                                <h6 className="mb-2">
                                    <span>1</span>
                                </h6>
                                {/* <GrowShrinkTag value={-21.12} suffix="%" /> */}
                            </div>
                        </div>
                    </Card>
                    <div className="card bg-gray-50 dark:bg-gray-700 border-0 card-shadow">
                        <div className="card-body">
                            <div className="flex items-center justify-between my-2">
                                <div className="flex items-center gap-1">
                                    <span className="avatar avatar-circle avatar-md bg-transparent">
                                        <GoPrimitiveDot
                                            size={'40px'}
                                            className="text-green-500"
                                        ></GoPrimitiveDot>
                                    </span>
                                    <div>
                                        <h6 className="font-bold">Open</h6>
                                        <p>View All</p>
                                    </div>
                                </div>
                                <div className="text-right rtl:text-left">
                                    <h6 className="mb-2">
                                        <span>0</span>
                                    </h6>
                                    {/* <GrowShrinkTag value={21.12} suffix="%" /> */}
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="card bg-gray-50 dark:bg-gray-700 border-0 card-shadow">
                        <div className="card-body">
                            <div className="flex items-center justify-between my-2">
                                <div className="flex items-center gap-1">
                                    <span className="avatar avatar-circle avatar-md bg-transparent">
                                        <GoPrimitiveDot
                                            size={'40px'}
                                            className="text-orange-500"
                                        ></GoPrimitiveDot>
                                    </span>
                                    <div>
                                        <h6 className="font-bold">
                                            Payment Pending
                                        </h6>
                                        <p>View All</p>
                                    </div>
                                </div>
                                <div className="text-right rtl:text-left">
                                    <h6 className="mb-2">
                                        <span>1</span>
                                    </h6>
                                    {/* <GrowShrinkTag value={-21.12} suffix="%" /> */}
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="card bg-gray-50 dark:bg-gray-700 border-0 card-shadow">
                        <div className="card-body">
                            <div className="flex items-center justify-between my-2">
                                <div className="flex items-center gap-1">
                                    <span className="avatar avatar-circle avatar-md bg-transparent">
                                        <GoPrimitiveDot
                                            size={'40px'}
                                            className="text-red-500"
                                        ></GoPrimitiveDot>
                                    </span>
                                    <div>
                                        <h6 className="font-bold">Advance</h6>
                                        <p>View All</p>
                                    </div>
                                </div>
                                <div className="text-right rtl:text-left">
                                    <h6 className="mb-2">
                                        <span>1</span>
                                    </h6>
                                    {/* <GrowShrinkTag value={21.12} suffix="%" /> */}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </Card>
            {/* <Card>
                <div className="flex justify-between items-center mb-8">
                    <h4>Other Pending Task</h4>
                    <div>
                        <Link to={'/'}>
                            <Button size="sm" variant="solid" color="blue-600" className="mr-2">Add Task</Button>
                        </Link>
                    </div>
                </div>
                <DataTable
                    columns={columns}
                    data={data}
                    loading={loading}
                    pagingData={{
                        total: tableData.total,
                        pageIndex: tableData.pageIndex,
                        pageSize: tableData.pageSize,
                    }}
                    onPaginationChange={handlePaginationChange}
                    onSelectChange={handleSelectChange}
                    columnShow={"true"}
                />
            </Card> */}
        </>
    )
}

export default Home
